window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-327ae69385f3c531"]={"versions": [{"id": "FIG-327ae69385f3c531", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- bzw. Include-Abhängigkeitsdiagramm für das AUTOSAR-Basissoftwaremodul Time Service (<code>Tm</code>). Das Diagramm visualisiert die statische Inklusionshierarchie zwischen Header-Dateien und Quelldateien des Moduls sowie externen Schnittstellen-Headern der AUTOSAR-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Dateientitäten und Inklusionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Tm.c</code>: C-Quelldateien des Time-Service-Moduls (symbolisiert als gestapelte Dateiblöcke).</li>\n<li><code>Tm.h</code>: Zentraler Modul-Header des Time Service.</li>\n<li><code>Tm_Cfg.h</code>: Vorkompilierungs-Konfigurations-Header.</li>\n<li><code>Std_Types.h</code>: Standard-AUTOSAR-Basistypen.</li>\n<li><code>Tm_MemMap.h</code>: Speicherkartierungs-Header des Moduls.</li>\n<li><code>SchM_Tm.h</code>: Header des Basic Software Scheduler für Exklusionsbereiche.</li>\n<li><code>Gpt.h</code>: Header des General Purpose Timer Treibers (MCAL).</li>\n<li><code>Det.h</code>: Header des Default/Development Error Tracers.</li>\n</ul>\n<p class=\"fig-p\">Inklusionsbeziehungen (Kanten mit Pfeilrichtung „includes“):</p>\n<ul class=\"fig-list\">\n<li><code>Tm.c</code> inkludiert <code>Tm.h</code>, <code>Tm_MemMap.h</code>, <code>SchM_Tm.h</code>, <code>Gpt.h</code> sowie bedingt <code>Det.h</code>.</li>\n<li><code>Tm.h</code> inkludiert <code>Std_Types.h</code> und <code>Tm_Cfg.h</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Dateistrukturdiagramm bildet die Abbildung keinen zeitlichen Kontrollfluss oder dynamischen Nachrichtenablauf ab. Sie legt die statischen Übersetzungsabhängigkeiten und Inklusionspfade für den Build-Prozess fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Inklusionen definieren normative Vorgaben für die Implementierung des Time-Service-Treibers:</p>\n<ul class=\"fig-list\">\n<li><code>Tm.c</code> muss <code>Tm.h</code>, <code>Tm_MemMap.h</code>, <code>SchM_Tm.h</code> und <code>Gpt.h</code> standardmäßig inkludieren.</li>\n<li>Die Inklusion von <code>Det.h</code> durch <code>Tm.c</code> ist optional und gestrichelt dargestellt; sie erfolgt ausschließlich dann, wenn Development Error Detection aktiviert ist („included, if development error detection is switched on“).</li>\n<li><code>Tm.h</code> stellt sicher, dass <code>Std_Types.h</code> und <code>Tm_Cfg.h</code> bereitgestellt werden.</li>\n</ul>"}, {"id": "FIG-06a789a20960bb89", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- bzw. Include-Abhängigkeitsdiagramm für das AUTOSAR-Basissoftwaremodul Time Service (<code>Tm</code>). Das Diagramm visualisiert die statische Inklusionshierarchie zwischen Header-Dateien und Quelldateien des Moduls sowie externen Schnittstellen-Headern der AUTOSAR-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Dateientitäten und Inklusionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Tm.c</code>: C-Quelldateien des Time-Service-Moduls (symbolisiert als gestapelte Dateiblöcke).</li>\n<li><code>Tm.h</code>: Zentraler Modul-Header des Time Service.</li>\n<li><code>Tm_Cfg.h</code>: Vorkompilierungs-Konfigurations-Header.</li>\n<li><code>Std_Types.h</code>: Standard-AUTOSAR-Basistypen.</li>\n<li><code>Tm_MemMap.h</code>: Speicherkartierungs-Header des Moduls.</li>\n<li><code>SchM_Tm.h</code>: Header des Basic Software Scheduler für Exklusionsbereiche.</li>\n<li><code>Gpt.h</code>: Header des General Purpose Timer Treibers (MCAL).</li>\n<li><code>Det.h</code>: Header des Default/Development Error Tracers.</li>\n</ul>\n<p class=\"fig-p\">Inklusionsbeziehungen (Kanten mit Pfeilrichtung „includes“):</p>\n<ul class=\"fig-list\">\n<li><code>Tm.c</code> inkludiert <code>Tm.h</code>, <code>Tm_MemMap.h</code>, <code>SchM_Tm.h</code>, <code>Gpt.h</code> sowie bedingt <code>Det.h</code>.</li>\n<li><code>Tm.h</code> inkludiert <code>Std_Types.h</code> und <code>Tm_Cfg.h</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Dateistrukturdiagramm bildet die Abbildung keinen zeitlichen Kontrollfluss oder dynamischen Nachrichtenablauf ab. Sie legt die statischen Übersetzungsabhängigkeiten und Inklusionspfade für den Build-Prozess fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Inklusionen definieren normative Vorgaben für die Implementierung des Time-Service-Treibers:</p>\n<ul class=\"fig-list\">\n<li><code>Tm.c</code> muss <code>Tm.h</code>, <code>Tm_MemMap.h</code>, <code>SchM_Tm.h</code> und <code>Gpt.h</code> standardmäßig inkludieren.</li>\n<li>Die Inklusion von <code>Det.h</code> durch <code>Tm.c</code> ist optional und gestrichelt dargestellt; sie erfolgt ausschließlich dann, wenn Default Error Detection aktiviert ist („included, if default error detection is switched on“).</li>\n<li><code>Tm.h</code> stellt sicher, dass <code>Std_Types.h</code> und <code>Tm_Cfg.h</code> bereitgestellt werden.</li>\n</ul>"}, {"id": "FIG-ccac58868bb1f56f", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- bzw. Include-Abhängigkeitsdiagramm für das AUTOSAR-Basissoftwaremodul Time Service (<code>Tm</code>). Das Diagramm visualisiert die statische Inklusionshierarchie zwischen Header-Dateien und Quelldateien des Moduls sowie externen Schnittstellen-Headern der AUTOSAR-Architektur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Dateientitäten und Inklusionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Tm.c</code>: C-Quelldateien des Time-Service-Moduls (symbolisiert als gestapelte Dateiblöcke).</li>\n<li><code>Tm.h</code>: Zentraler Modul-Header des Time Service.</li>\n<li><code>Tm_Cfg.h</code>: Vorkompilierungs-Konfigurations-Header.</li>\n<li><code>Std_Types.h</code>: Standard-AUTOSAR-Basistypen.</li>\n<li><code>Tm_MemMap.h</code>: Speicherkartierungs-Header des Moduls.</li>\n<li><code>SchM_Tm.h</code>: Header des Basic Software Scheduler für Exklusionsbereiche.</li>\n<li><code>Gpt.h</code>: Header des General Purpose Timer Treibers (MCAL).</li>\n<li><code>Det.h</code>: Header des Default Error Tracers.</li>\n</ul>\n<p class=\"fig-p\">Inklusionsbeziehungen (Kanten mit Pfeilrichtung „includes“):</p>\n<ul class=\"fig-list\">\n<li><code>Tm.c</code> inkludiert durchgezogen <code>Tm.h</code>, <code>Tm_MemMap.h</code>, <code>SchM_Tm.h</code>, <code>Gpt.h</code> und <code>Det.h</code>.</li>\n<li><code>Tm.h</code> inkludiert <code>Std_Types.h</code> und <code>Tm_Cfg.h</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Dateistrukturdiagramm bildet die Abbildung keinen zeitlichen Kontrollfluss oder dynamischen Nachrichtenablauf ab. Sie legt die statischen Übersetzungsabhängigkeiten und Inklusionspfade für den Build-Prozess fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Inklusionen definieren normative Vorgaben für die Implementierung des Time-Service-Treibers:</p>\n<ul class=\"fig-list\">\n<li><code>Tm.c</code> inkludiert <code>Tm.h</code>, <code>Tm_MemMap.h</code>, <code>SchM_Tm.h</code>, <code>Gpt.h</code> sowie <code>Det.h</code> als reguläre, unbedingte Include-Beziehungen über durchgezogene Pfeile.</li>\n<li><code>Tm.h</code> stellt sicher, dass <code>Std_Types.h</code> und <code>Tm_Cfg.h</code> bereitgestellt werden.</li>\n</ul>"}], "trans": [{"from": "FIG-327ae69385f3c531", "to": "FIG-06a789a20960bb89", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Anmerkung an der gestrichelten Include-Kante von <code>Tm.c</code> zu <code>Det.h</code>: Ersetzung der Textbezeichnung „development error detection“ durch „default error detection“.</li>\n</ul>"}, {"from": "FIG-06a789a20960bb89", "to": "FIG-ccac58868bb1f56f", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kante von <code>Tm.c</code> zu <code>Det.h</code>: Die Beziehung ist nicht mehr als gestrichelte Pfeillinie mit der Bedingung „(included, if default error detection is switched on)“ dargestellt, sondern als durchgezogene, unbedingte Include-Kante; die textuelle Bedingungsanmerkung entfällt.</li>\n</ul>"}]};
